/* Responsive owner-scoped Projects workspace. Uses canonical PWA APIs for data and AI turns. */
let projectRows=[],projectCurrent=null,projectTab='overview',projectListQuery='',projectListFilter='all',projectListSort='recent',projectListView='grid',projectChatBusy=false;
const projectTabs=[['overview','Overview'],['chat','Chat'],['plan','Work plan'],['files','Files & sources'],['approvals','Approvals'],['discussions','Discussions'],['activity','Activity'],['live','Live work'],['status','3D status'],['structure','Project structure']];
function prEsc(value){const node=document.createElement('span');node.textContent=String(value??'');return node.innerHTML}
function prDate(value){if(!value)return 'No date';const date=new Date(value.length===10?value+'T12:00:00':value);return Number.isNaN(date.getTime())?String(value):date.toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'})}
function prRelative(value){if(!value)return 'Recently';const date=new Date(value);if(Number.isNaN(date.getTime()))return 'Recently';return new Intl.RelativeTimeFormat(undefined,{numeric:'auto'}).format(Math.round((date-Date.now())/86400000),'day')}
function prCount(project){return Number(project.task_count||0)}
function prProgress(project){const count=prCount(project);return count?Math.round(Number(project.done_count||0)*100/count):0}
function prEmpty(title,copy,action=''){return `<div class="project-empty"><span class="project-empty-icon" aria-hidden="true">◇</span><h2>${prEsc(title)}</h2><p>${prEsc(copy)}</p>${action}</div>`}
function prButton(label,action,kind=''){return `<button type="button" class="project-btn ${kind}" data-project-action="${prEsc(action)}">${prEsc(label)}</button>`}
function prLoading(message='Loading project workspace…'){return `<div class="project-loading" role="status">${prEsc(message)}</div>`}
function prError(error,retry){return `<section class="project-error" role="alert"><strong>${prEsc(error?.message||'Could not load project data.')}</strong><p>Project data remains saved. Try again when the connection is available.</p>${prButton('Retry',retry,'primary')}</section>`}

function projectDialog(title,fields,initial={}){
 return new Promise(resolve=>{
  const dialog=document.createElement('dialog');dialog.className='project-dialog';dialog.setAttribute('aria-labelledby','projectDialogTitle');
  const form=document.createElement('form');form.className='project-dialog-form';form.method='dialog';
  const head=document.createElement('header');head.className='project-dialog-head';const heading=document.createElement('h2');heading.id='projectDialogTitle';heading.textContent=title;const close=document.createElement('button');close.className='project-dialog-close';close.type='button';close.setAttribute('aria-label','Close dialog');close.textContent='×';head.append(heading,close);
  const content=document.createElement('div');content.className='project-dialog-fields';
  for(const field of fields){const label=document.createElement(field.type==='checklist'?'fieldset':'label');if(field.type==='checklist'){label.className='project-checklist-field';const legend=document.createElement('legend');legend.textContent=field.label;label.append(legend)}else label.append(document.createTextNode(field.label));let control;
   if(field.type==='textarea'){control=document.createElement('textarea');control.rows=field.rows||3}
   else if(field.type==='select'){control=document.createElement('select');for(const [value,text] of field.options){const option=document.createElement('option');option.value=value;option.textContent=text;control.append(option)}}
   else if(field.type==='checklist'){control=document.createElement('span');control.className='project-checklist';for(const [value,text] of field.options){const row=document.createElement('label');const checkbox=document.createElement('input');checkbox.type='checkbox';checkbox.name=field.name;checkbox.value=value;checkbox.checked=Array.isArray(initial[field.name])&&initial[field.name].includes(value);const copy=document.createElement('span');copy.textContent=text;row.append(checkbox,copy);control.append(row)}}
   else if(field.type==='note'){control=document.createElement('small');control.className='project-dialog-note';control.textContent=field.value||''}
   else {control=document.createElement('input');control.type=field.type||'text';if(field.type==='date')control.min=new Date().toISOString().slice(0,10)}
   if(field.type!=='checklist'&&field.type!=='note'){control.name=field.name;control.value=initial[field.name]??field.value??'';control.required=Boolean(field.required);if(field.placeholder)control.placeholder=field.placeholder;if(field.maxLength)control.maxLength=field.maxLength}label.append(control);content.append(label)
  }
  if(title==='Add task'||title==='Edit task') {const note=document.createElement('p');note.className='project-dialog-note';note.textContent='Assigning a task to Vishnu records ownership only. It does not start execution.';content.append(note)}
  const actions=document.createElement('footer');actions.className='project-dialog-actions';const cancel=document.createElement('button');cancel.className='project-btn quiet';cancel.type='button';cancel.textContent='Cancel';const save=document.createElement('button');save.className='project-btn primary';save.type='submit';save.textContent='Save';actions.append(cancel,save);form.append(head,content,actions);dialog.append(form);document.body.append(dialog);
  let outcome=null;const closeDialog=()=>{if(dialog.open)dialog.close();dialog.remove();resolve(outcome)};close.onclick=cancel.onclick=closeDialog;
  form.addEventListener('submit',event=>{event.preventDefault();const data=new FormData(form);outcome=Object.fromEntries(data.entries());for(const field of fields)if(field.type==='checklist')outcome[field.name]=data.getAll(field.name);for(const [key,value] of Object.entries(outcome))if(value==='')outcome[key]=null;closeDialog()});
  head.addEventListener('pointerdown',event=>{if(event.target===close)return;const rect=dialog.getBoundingClientRect(),dx=event.clientX-rect.left,dy=event.clientY-rect.top;head.setPointerCapture?.(event.pointerId);const move=e=>{dialog.style.margin='0';dialog.style.left=Math.max(8,Math.min(innerWidth-dialog.offsetWidth-8,e.clientX-dx))+'px';dialog.style.top=Math.max(8,Math.min(innerHeight-dialog.offsetHeight-8,e.clientY-dy))+'px'};const stop=()=>{head.removeEventListener('pointermove',move);head.removeEventListener('pointerup',stop)};head.addEventListener('pointermove',move);head.addEventListener('pointerup',stop,{once:true})});
  dialog.addEventListener('cancel',event=>{event.preventDefault();closeDialog()});dialog.addEventListener('click',event=>{if(event.target===dialog)closeDialog()});dialog.showModal();content.querySelector('input,textarea,select')?.focus()
 })
}

function projectStatusLabel(project){
 if(project.status==='paused')return 'Paused';
 if(project.status==='archived')return 'Archived';
 if(project.status==='completed'||(Number(project.task_count)>0&&Number(project.done_count)===Number(project.task_count)))return 'Completed';
 if(Number(project.review_count)>0)return 'Needs review';
 return 'Active';
}
function projectPreviewExamples(){
 const now=Date.now(),updated=hours=>new Date(now-hours*3600000).toISOString();
 return [
  {id:'demo-project-personal-ai',demo:true,name:'Personal AI mobile workspace',goal:'Polish the mobile project experience and verify the core workspace flows.',project_type:'software',status:'active',task_count:5,done_count:3,review_count:1,milestone_count:2,current_task:'Refine the full-screen project setup flow',updated_at:updated(2),created_at:updated(96),target_date:new Date(now+14*86400000).toISOString().slice(0,10)},
  {id:'demo-project-visual-architecture',demo:true,name:'Visual Architecture Agent',goal:'Build clear architecture maps from project code and natural-language briefs.',project_type:'research',status:'active',task_count:4,done_count:1,review_count:0,milestone_count:3,current_task:'Review the architecture brief',updated_at:updated(7),created_at:updated(240)},
  {id:'demo-project-perspective',demo:true,name:'The Perspective',goal:'Plan a public website and editorial publishing experience.',project_type:'writing',status:'paused',task_count:6,done_count:2,review_count:0,milestone_count:2,current_task:'Resume the editorial structure review',updated_at:updated(72),created_at:updated(480)},
  {id:'demo-project-knowledge',demo:true,name:'Personal knowledge system',goal:'Organize a private reference library and planning workflow.',project_type:'personal',status:'completed',task_count:4,done_count:4,review_count:0,milestone_count:2,updated_at:updated(168),created_at:updated(720)}
 ];
}
function projectResumeCandidate(){return projectRows.filter(p=>['active','paused'].includes(p.status)&&((p.task_count||0)>0||p.goal)).sort((a,b)=>String(b.updated_at||'').localeCompare(String(a.updated_at||'')))[0]||null}
async function loadProjectList(){
 const host=document.getElementById('moduleBody');host.innerHTML=prLoading('Loading your projects…');
 try{const status=projectListFilter==='archived'?'archived':'all';const data=await api('/projects?status='+status);projectRows=Array.isArray(data.projects)?data.projects:[];if(typeof personalAiDemoMode!=='undefined'&&personalAiDemoMode&&projectListFilter!=='archived')projectRows=projectPreviewExamples();projectCurrent=null;projectTab='overview';renderProjectList()}
 catch(error){host.innerHTML=`<div class="project-page"><div class="project-heading"><div><h1>Projects</h1><p>Your ongoing work with Vishnu, organized in one place.</p></div></div>${prError(error,'reload')}</div>`;bindProjectActions()}
}
function renderProjectList(){
 const host=document.getElementById('moduleBody'),q=projectListQuery.trim().toLowerCase();let rows=projectRows.filter(item=>!q||`${item.name} ${item.goal} ${item.description} ${item.project_type||''}`.toLowerCase().includes(q));
 if(projectListFilter==='active')rows=rows.filter(item=>projectStatusLabel(item)==='Active');
 if(projectListFilter==='needs_review')rows=rows.filter(item=>projectStatusLabel(item)==='Needs review');
 if(projectListFilter==='completed')rows=rows.filter(item=>projectStatusLabel(item)==='Completed');
 if(projectListFilter==='paused')rows=rows.filter(item=>item.status==='paused');
 if(projectListFilter==='archived')rows=rows.filter(item=>item.status==='archived');
 rows=rows.slice().sort((a,b)=>projectListSort==='name'?a.name.localeCompare(b.name):projectListSort==='created'?String(b.created_at||'').localeCompare(String(a.created_at||'')):String(b.updated_at||'').localeCompare(String(a.updated_at||'')));
 const candidate=projectListFilter==='all'?projectResumeCandidate():null;
 const card=project=>{const status=projectStatusLabel(project),progress=prProgress(project),hasProgress=prCount(project)>0,working=(project.tasks||[]).find(task=>task.status==='in_progress'&&task.owner==='vishnu'),activity=project.current_task||working?.title||'';return `<article class="project-card project-card-rich"><div class="project-art" aria-hidden="true"><span>${prEsc((project.name||'P').trim().slice(0,1).toUpperCase())}</span></div><div class="project-card-copy"><div class="project-card-head"><div><h2>${prEsc(project.name)}</h2><p>${prEsc(project.goal||project.description||'No description added yet.')}</p></div><span class="project-tag ${status==='Active'?'active':status==='Completed'?'done':status==='Needs review'?'review':status==='Paused'?'paused':''}">${prEsc(status)}</span></div>${hasProgress?`<div class="project-progress"><span>${Number(project.done_count||0)} of ${prCount(project)} tasks complete</span><span>${progress}%</span><span class="project-progress-track"><i style="width:${progress}%"></i></span></div>`:''}<div class="project-card-current">${activity?`<span class="project-card-activity"><i class="project-dot ${working?'':''}" aria-hidden="true"></i>${working?'Vishnu is working · ':''}${prEsc(activity)}</span>`:`<span>${Number(project.milestone_count||0)} milestones · ${prCount(project)} tasks</span>`}${Number(project.review_count)>0?`<span class="project-review-count">${Number(project.review_count)} ${Number(project.review_count)===1?'needs':'need'} review</span>`:''}</div><footer class="project-card-foot"><span>Updated ${prEsc(prRelative(project.updated_at))}${project.target_date?' · Target '+prEsc(prDate(project.target_date)):''}</span><div class="project-card-actions">${project.demo?'':`<details class="project-overflow"><summary aria-label="Project actions for ${prEsc(project.name)}" title="Project actions">⋯</summary><div class="project-overflow-menu">${project.status==='archived'?`<button type="button" data-project-restore="${prEsc(project.id)}">Restore</button>`:`<button type="button" data-project-edit="${prEsc(project.id)}">Edit details</button><button type="button" data-project-archive="${prEsc(project.id)}">Archive project</button>`}</div></details>`}<button type="button" class="project-btn ${status==='Paused'?'':'primary'}" data-project-open="${prEsc(project.id)}">${project.demo?'Preview':status==='Paused'?'Resume':status==='Completed'?'View project':'Open'} <span aria-hidden="true">→</span></button></div></footer></div></article>`};
 const filters=[['all','All projects'],['active','Active'],['needs_review','Needs review'],['completed','Completed'],['archived','Archived']];
 host.innerHTML=`<div class="project-page project-list-page"><header class="project-heading"><div><h1>Projects</h1><p>Your ongoing work with Vishnu, organized in one place.</p></div>${prButton('+ New project','new-project','primary')}</header>${projectRows.some(project=>project.demo)?'<p class="project-demo-notice" role="status">Preview data · sample projects only; these records are not saved to your account.</p>':''}${candidate?`<section class="project-resume-card"><div class="project-resume-content"><small>CONTINUE WHERE YOU LEFT OFF</small><h2>${prEsc(candidate.name)}</h2><span class="project-tag ${candidate.status==='paused'?'paused':'active'}">${candidate.status==='paused'?'Paused':'Active'}</span><p>${prEsc(candidate.goal||candidate.description||'Continue in this workspace.')}</p>${prCount(candidate)?`<div class="project-resume-progress"><span class="project-progress-track"><i style="width:${prProgress(candidate)}%"></i></span><b>${prProgress(candidate)}%</b></div>`:''}<div class="project-card-current">${candidate.current_task?`<span>${prEsc(candidate.current_task)}</span>`:`<span>${prCount(candidate)} ${prCount(candidate)===1?'task':'tasks'} · ${Number(candidate.milestone_count||0)} milestones</span>`}${Number(candidate.review_count)>0?`<span class="project-review-count">${Number(candidate.review_count)} needs review</span>`:''}</div></div><button type="button" class="project-btn primary" data-project-open="${prEsc(candidate.id)}">${candidate.demo?'Preview':candidate.status==='paused'?'Resume':'Open'} project <span aria-hidden="true">→</span></button></section>`:''}<div class="project-toolbar project-list-toolbar"><label class="project-search-wrap"><span aria-hidden="true">⌕</span><input id="projectSearch" class="project-search" type="search" placeholder="Search projects…" value="${prEsc(projectListQuery)}" aria-label="Search projects"></label><div class="project-filter-strip" role="group" aria-label="Project status filter">${filters.map(([key,label])=>`<button class="project-filter-chip" type="button" data-project-filter="${key}" aria-pressed="${projectListFilter===key}">${label}</button>`).join('')}</div><div class="project-list-controls"><label class="project-sort-label"><span class="sr-only">Sort projects</span><select id="projectSort" class="project-filter" aria-label="Sort projects"><option value="recent" ${projectListSort==='recent'?'selected':''}>Recently active</option><option value="name" ${projectListSort==='name'?'selected':''}>Name</option><option value="created" ${projectListSort==='created'?'selected':''}>Recently created</option></select></label><div class="project-view-switch" role="group" aria-label="Project display"><button type="button" data-project-view="grid" aria-pressed="${projectListView==='grid'}" aria-label="Grid view">▦</button><button type="button" data-project-view="list" aria-pressed="${projectListView==='list'}" aria-label="List view">☰</button></div></div></div><div class="project-results-heading"><span>${rows.length} ${rows.length===1?'project':'projects'}</span><span>Archived projects stay searchable.</span></div>${rows.length?`<div class="project-grid ${projectListView==='list'?'is-list':''}">${rows.map(card).join('')}</div>`:prEmpty(projectListQuery||projectListFilter!=='all'?'No matching projects':'Your project work starts here',projectListQuery||projectListFilter!=='all'?'Try another search or status filter.':'Projects keep a goal, tasks, milestones, sources, and Vishnu’s project-specific context together. Create a workspace when you have real work to organize.',prButton('+ New project','new-project','primary'))}</div>`;
 const search=document.getElementById('projectSearch');search?.addEventListener('input',()=>{projectListQuery=search.value;renderProjectList();const next=document.getElementById('projectSearch');next?.focus();next?.setSelectionRange(next.value.length,next.value.length)});
 document.getElementById('projectSort')?.addEventListener('change',event=>{projectListSort=event.target.value;renderProjectList()});host.querySelectorAll('[data-project-filter]').forEach(button=>button.onclick=()=>{projectListFilter=button.dataset.projectFilter;if(projectListFilter==='archived')loadProjectList();else if(projectRows.some(item=>item.status==='archived'))loadProjectList();else renderProjectList()});host.querySelectorAll('[data-project-view]').forEach(button=>button.onclick=()=>{projectListView=button.dataset.projectView;renderProjectList()});host.querySelectorAll('[data-project-open]').forEach(button=>button.onclick=async()=>{const item=projectRows.find(project=>project.id===button.dataset.projectOpen);if(item?.demo){showToast('Preview project only — demo records are not saved or editable.');return}if(item?.status==='paused'){try{await api('/projects/'+encodeURIComponent(item.id),{method:'PATCH',body:JSON.stringify({status:'active'})});showToast('Project resumed.')}catch(error){showToast(error.message);return}}openProject(button.dataset.projectOpen)});host.querySelectorAll('[data-project-edit]').forEach(button=>button.onclick=()=>{const item=projectRows.find(project=>project.id===button.dataset.projectEdit);if(item)editProjectFromList(item)});host.querySelectorAll('[data-project-archive]').forEach(button=>button.onclick=()=>archiveProject(button.dataset.projectArchive));host.querySelectorAll('[data-project-restore]').forEach(button=>button.onclick=()=>restoreProject(button.dataset.projectRestore));bindProjectActions()
}
function projectSummary(project){return `${project.name}${project.goal?': '+project.goal:''}`}
async function openProject(projectId,tab='overview'){
 projectTab=tab;const host=document.getElementById('moduleBody');host.innerHTML=prLoading('Opening project…');
 try{const data=await api('/projects/'+encodeURIComponent(projectId));projectCurrent=data.project;renderProjectDetail()}
 catch(error){host.innerHTML=`<div class="project-page">${prError(error,'reload')}</div>`;bindProjectActions()}
}
function projectPageHead(){const p=projectCurrent;return `<div class="project-breadcrumb"><button type="button" data-project-action="back">Projects</button><span aria-hidden="true">›</span><span>${prEsc(p.name)}</span></div><header class="project-detail-head"><div class="project-detail-title"><span class="project-detail-icon" aria-hidden="true">◇</span><div><h1>${prEsc(p.name)}</h1><p>${prEsc(p.goal||p.description||'Add a goal so Vishnu understands the outcome you want.')}</p></div></div><div class="project-actions">${prButton('Edit project','edit-project')}${p.status==='paused'?prButton('Resume project','resume-project','primary'):prButton('Pause project','pause-project','quiet')}${prButton('Ask Vishnu','go-chat','primary')}</div></header><nav class="project-tabbar" aria-label="Project sections" role="tablist">${projectTabs.map(([key,label])=>`<button class="project-tab" role="tab" type="button" aria-selected="${projectTab===key}" data-project-tab="${key}">${label}</button>`).join('')}</nav>`}
function renderProjectDetail(){const host=document.getElementById('moduleBody'),p=projectCurrent;if(!p)return;host.innerHTML=`<div class="project-page">${projectPageHead()}<div id="projectTabContent"></div></div>`;host.querySelectorAll('[data-project-tab]').forEach(button=>button.onclick=()=>{projectTab=button.dataset.projectTab;renderProjectDetail()});bindProjectActions();renderProjectTab()}
function renderProjectTab(){const host=document.getElementById('projectTabContent'),p=projectCurrent;if(!host||!p)return;
 if(projectTab==='overview')return renderProjectOverview(host,p);
 if(projectTab==='chat')return renderProjectChat(host,p);
 if(projectTab==='plan')return renderProjectPlan(host,p);
 if(projectTab==='files')return renderProjectFiles(host,p);
 if(projectTab==='approvals')return renderProjectApprovals(host,p);
 if(projectTab==='discussions')return renderProjectDiscussions(host,p);
 if(projectTab==='activity')return renderProjectActivity(host,p);
 if(projectTab==='live')return renderProjectLive(host,p);
 if(projectTab==='status')return renderProjectStatus(host,p);
 if(projectTab==='structure')return renderProjectStructure(host,p);
}
function renderProjectOverview(host,p){const active=p.tasks.filter(task=>task.status==='in_progress'),next=p.tasks.filter(task=>task.status!=='done').slice(0,4),milestones=p.milestones.slice(0,4);host.innerHTML=`<div class="project-overview-grid"><section class="project-panel"><h2>Project health</h2><div class="project-stat-grid"><div class="project-stat"><strong>${prProgress(p)}%</strong><span>Task progress</span></div><div class="project-stat"><strong>${p.tasks.length}</strong><span>Tasks</span></div><div class="project-stat"><strong>${p.milestones.length}</strong><span>Milestones</span></div></div><div class="project-progress" style="margin-top:16px"><span>Overall completion</span><span>${Number(p.done_count||0)}/${p.tasks.length||0}</span><span class="project-progress-track"><i style="width:${prProgress(p)}%"></i></span></div><p class="project-muted">${p.target_date?'Target date: '+prEsc(prDate(p.target_date)):'Set a target date when the project needs one.'}</p></section><section class="project-panel"><h2>Vishnu’s work</h2>${active.length?`<div class="project-inline-list">${active.map(task=>`<div class="project-item-row"><i class="project-dot"></i><div><strong>${prEsc(task.title)}</strong><small>In progress · ${prEsc(task.owner==='vishnu'?'Assigned to Vishnu':'Owner task')}</small></div><button type="button" class="project-btn quiet" data-project-task-edit="${prEsc(task.id)}">View</button></div>`).join('')}</div>`:prEmpty('No active work yet','Ask Vishnu about a task to start a project-scoped conversation.')}${prButton('Open project chat','go-chat','quiet')}</section><section class="project-panel"><div class="project-section-head"><h2>Next tasks</h2>${prButton('Add task','new-task','quiet')}</div>${next.length?`<div class="project-inline-list">${next.map(task=>`<div class="project-item-row"><i class="project-dot ${task.status==='blocked'?'blocked':task.status==='done'?'done':task.status==='paused'?'paused':''}"></i><div><strong>${prEsc(task.title)}</strong><small>${prEsc(task.status.replaceAll('_',' '))} · ${prEsc(task.priority)} priority${task.due_date?' · due '+prEsc(prDate(task.due_date)):''}</small></div><button type="button" class="project-btn quiet" data-project-ask-task="${prEsc(task.id)}">Ask Vishnu</button></div>`).join('')}</div>`:prEmpty('No tasks planned','Add the next concrete step for this project.')}</section><section class="project-panel"><div class="project-section-head"><h2>Milestones</h2>${prButton('Add milestone','new-milestone','quiet')}</div>${milestones.length?`<div class="project-milestones">${milestones.map(m=>`<div class="project-milestone"><i class="project-dot ${m.status==='done'?'done':''}"></i><div><strong>${prEsc(m.title)}</strong><p>${prEsc(m.outcome||'Outcome not defined')}${m.target_date?' · '+prEsc(prDate(m.target_date)):''}</p></div><span class="project-tag">${prEsc(m.status.replaceAll('_',' '))}</span></div>`).join('')}</div>`:prEmpty('No milestones yet','Break the goal into outcomes with target dates.')}</section></div>`;bindProjectActions()}
function projectMessageText(event){try{const parsed=eventMessage(event);return parsed?.text||event?.payload?.text||''}catch{return event?.payload?.text||''}}
function projectMessageKind(event){const parsed=eventMessage(event);return (parsed?.role==='user'||event?.kind==='user_message')?'owner':'vishnu'}
async function renderProjectChat(host,p){host.innerHTML=prLoading('Loading project conversation…');let events=[];try{if(p.conversation_id){const result=await api('/conversations/'+encodeURIComponent(p.conversation_id));events=result.events||[]}}catch(error){if(error.status!==404){host.innerHTML=`<div class="project-panel">${prError(error,'project-chat-retry')}</div>`;bindProjectActions();return}}host.innerHTML=`<section class="project-panel project-chat"><div class="project-chat-log" id="projectChatLog" aria-live="polite">${events.map(event=>`<article class="project-chat-message ${projectMessageKind(event)}"><div>${prEsc(projectMessageText(event))}</div><small>${projectMessageKind(event)==='owner'?'You':'Vishnu'}</small></article>`).join('')||`<div class="project-empty"><span class="project-empty-icon">✦</span><h2>Project chat</h2><p>Vishnu will use this project’s goal and task list to keep the conversation focused.</p></div>`}</div><form class="project-chat-composer" id="projectChatForm"><textarea name="message" placeholder="Ask Vishnu about this project…" required maxlength="4000" aria-label="Message Vishnu about this project"></textarea><button class="project-btn primary" type="submit">Send to Vishnu</button><div class="project-chat-note">Tool use and external actions still follow Personal AI’s existing approval controls.</div></form></section>`;host.querySelector('#projectChatForm').onsubmit=event=>{event.preventDefault();const text=new FormData(event.currentTarget).get('message');sendProjectMessage(String(text||''))};const log=host.querySelector('#projectChatLog');log.scrollTop=log.scrollHeight}
async function projectChatContext(p,task=null){let sources=[];const attached=new Set(task?.file_ids||[]);const eligible=(p.files||[]).filter(item=>/\.(txt|md|csv)$/i.test(item.title));const chosen=[...eligible.filter(item=>attached.has(item.id)),...eligible.filter(item=>!attached.has(item.id))].slice(0,6);for(const file of chosen){try{const response=await fetch(`/iphone/api/projects/${encodeURIComponent(p.id)}/files/${encodeURIComponent(file.id)}/download`,{credentials:'same-origin'});if(!response.ok)continue;const text=(await response.text()).slice(0,1600);sources.push(`\n${attached.has(file.id)?'TASK ATTACHMENT':'PROJECT SOURCE'} ${file.title}:\n${text}`)}catch{}}return `Project name: ${p.name}\nProject goal: ${p.goal||'Not set'}\nProject description: ${p.description||'Not set'}\nCurrent project tasks: ${(p.tasks||[]).map(t=>`- [${t.status}] ${t.title}${t.description?': '+t.description:''}${t.context_notes?'\n  Context: '+t.context_notes:''}`).join('\n')||'None'}\nMilestones: ${(p.milestones||[]).map(m=>`- [${m.status}] ${m.title}${m.outcome?': '+m.outcome:''}`).join('\n')||'None'}\n${sources.join('\n')}\n\nUse this project context to answer the owner's request. Ask when important information is missing. Do not claim background work has started unless you start a governed operation.`.slice(0,7600)}
async function sendProjectMessage(text){if(projectChatBusy||!projectCurrent)return;const p=projectCurrent,host=document.getElementById('projectTabContent');projectChatBusy=true;const form=host.querySelector('#projectChatForm'),input=form?.querySelector('textarea'),submit=form?.querySelector('button[type=submit]');if(submit){submit.disabled=true;submit.textContent='Vishnu is working…'}const log=host.querySelector('#projectChatLog');if(log){const msg=document.createElement('article');msg.className='project-chat-message owner';msg.textContent=text;log.append(msg);const loading=document.createElement('article');loading.className='project-chat-message vishnu';loading.id='projectChatLoading';loading.textContent='Vishnu is thinking…';log.append(loading);log.scrollTop=log.scrollHeight}
 try{const conversation=await api('/projects/'+encodeURIComponent(p.id)+'/conversation',{method:'POST',body:'{}'});const selectedTask=(p.tasks||[]).find(task=>text.includes(task.title));const context=await projectChatContext(conversation.project||p,selectedTask);const result=await api('/voice/turn',{method:'POST',body:JSON.stringify({transcript:`${context}\n\nOwner request: ${text}`,conversation_id:conversation.conversation_id})});await api('/projects/'+encodeURIComponent(p.id)+'/activity',{method:'POST',body:JSON.stringify({content:text})}).catch(()=>{});if(result.status==='approval_required'){showToast('Vishnu needs approval for a tool action. Review it in Workflows.')}const fresh=await api('/projects/'+encodeURIComponent(p.id));projectCurrent=fresh.project;projectTab='chat';await renderProjectDetail()}
 catch(error){document.getElementById('projectChatLoading')?.remove();const failure=document.createElement('article');failure.className='project-chat-message vishnu';failure.setAttribute('role','alert');failure.textContent=error.message||'Vishnu could not respond. Try again.';log?.append(failure);if(input)input.value=text}
 finally{projectChatBusy=false}}
function renderProjectPlan(host,p){const statuses=[['planned','Planned'],['in_progress','In progress'],['blocked','Blocked'],['needs_review','Needs review'],['paused','Paused'],['done','Complete'],['failed','Failed']];const columns=statuses.map(([status,label])=>`<section class="project-plan-column"><h3>${label} · ${p.tasks.filter(t=>t.status===status).length}</h3>${p.tasks.filter(t=>t.status===status).map(task=>`<article class="project-task-card"><strong>${prEsc(task.title)}</strong>${task.description?`<p>${prEsc(task.description)}</p>`:''}${task.context_notes?`<p class="project-task-context">Context: ${prEsc(task.context_notes)}</p>`:''}${task.file_ids?.length?`<p class="project-task-context">Files: ${task.file_ids.map(id=>p.files.find(file=>file.id===id)?.title).filter(Boolean).map(prEsc).join(', ')}</p>`:''}<div class="project-task-foot"><span>${prEsc(task.owner==='vishnu'?'Vishnu':task.owner==='owner'?'You':task.owner)}</span><span>${prEsc(task.priority)}${task.due_date?' · '+prEsc(prDate(task.due_date)):''}</span></div><div class="project-actions"><button class="project-btn quiet" type="button" data-project-task-edit="${prEsc(task.id)}">Edit</button><button class="project-btn quiet" type="button" data-project-ask-task="${prEsc(task.id)}">Ask Vishnu</button><select aria-label="Change status for ${prEsc(task.title)}" data-project-task-status="${prEsc(task.id)}">${statuses.map(([v,t])=>`<option value="${v}" ${task.status===v?'selected':''}>${t}</option>`).join('')}</select></div></article>`).join('')||'<div class="project-muted">No tasks</div>'}</section>`).join('');host.innerHTML=`<div class="project-page"><div class="project-section-head"><h2>Tasks</h2>${prButton('＋ Add task','new-task','primary')}</div><div class="project-plan-grid">${columns}</div><section class="project-panel"><div class="project-section-head"><h2>Milestones</h2>${prButton('＋ Add milestone','new-milestone','quiet')}</div>${p.milestones.length?`<div class="project-milestones">${p.milestones.map(m=>`<article class="project-milestone"><i class="project-dot ${m.status==='done'?'done':''}"></i><div><strong>${prEsc(m.title)}</strong><p>${prEsc(m.outcome||'No outcome defined')}${m.target_date?' · '+prEsc(prDate(m.target_date)):''}</p>${m.completion_criteria?`<p>Criteria: ${prEsc(m.completion_criteria)}</p>`:''}<small>${(m.task_ids||[]).length} linked ${(m.task_ids||[]).length===1?'task':'tasks'}</small></div><button type="button" class="project-btn quiet" data-project-milestone-edit="${prEsc(m.id)}">Edit</button></article>`).join('')}</div>`:prEmpty('No milestones yet','Create outcome checkpoints for this project.')}</section></div>`;host.querySelectorAll('[data-project-task-status]').forEach(select=>select.onchange=()=>updateProjectTask(select.dataset.projectTaskStatus,{status:select.value}));bindProjectActions()}
function renderProjectFiles(host,p){const supported=new Set(['txt','md','csv']);const rows=p.files.map(file=>{const ext=(file.title.split('.').pop()||'').toLowerCase(),usable=file.kind==='link'||supported.has(ext);return `<article class="project-file-row"><span class="project-file-icon">${file.kind==='link'?'↗':'▤'}</span><div><strong>${prEsc(file.title)}</strong><small>${file.kind==='link'?prEsc(file.url):`${prEsc(ext.toUpperCase()||'FILE')} · ${file.size_bytes?`${(Number(file.size_bytes)/1024).toFixed(0)} KB · `:''}${usable?'Text source available in project chat':'Stored for download; not indexed for project chat'} · ${prEsc(prDate(file.created_at))}`}</small></div>${file.kind==='link'?`<a class="project-btn quiet" href="${prEsc(file.url)}" target="_blank" rel="noopener noreferrer">Open source</a>`:`<a class="project-btn quiet" href="/iphone/api/projects/${encodeURIComponent(p.id)}/files/${encodeURIComponent(file.id)}/download">Download</a>`}</article>`}).join('');host.innerHTML=`<div class="project-page"><section class="project-panel"><div class="project-section-head"><div><h2>Files &amp; sources</h2><p class="project-muted">Files are stored under this project. Only supported text formats are included in project chat context.</p></div><button type="button" class="project-btn primary" data-project-action="add-files">＋ Add files &amp; sources</button></div><div class="project-inline-list">${rows||prEmpty('No project files yet','Upload a source file or add a trusted web link. External connector integrations are not configured.')}</div></section></div>`;bindProjectActions()}

function renderProjectApprovals(host,p){const files=new Map((p.files||[]).map(file=>[file.id,file.title])),tasks=new Map((p.tasks||[]).map(task=>[task.id,task.title]));host.innerHTML=`<div class="project-page"><section class="project-panel"><div class="project-section-head"><div><h2>Proposal approvals</h2><p class="project-muted">Record review decisions for a specific project proposal. Approval does not start work or authorize other actions.</p></div><button type="button" class="project-btn primary" data-project-action="new-proposal">＋ New proposal</button></div>${p.approvals?.length?`<div class="project-inline-list">${p.approvals.map(item=>`<article class="project-approval-row"><div><strong>${prEsc(item.title)}</strong><small>${prEsc(item.status.replaceAll('_',' '))} · proposed ${prEsc(prDate(item.proposed_at))}</small><small>${prEsc(item.summary)}</small>${item.reviewer_comments?`<small>Reviewer comments: ${prEsc(item.reviewer_comments)}</small>`:''}<small>${(item.task_ids||[]).map(id=>tasks.get(id)).filter(Boolean).map(prEsc).join(' · ')||'No linked tasks'}${item.file_ids?.length?' · Files: '+item.file_ids.map(id=>files.get(id)).filter(Boolean).map(prEsc).join(', '):''}</small></div><button class="project-btn quiet" type="button" data-proposal-review="${prEsc(item.id)}">${item.status==='pending'?'Review':item.status==='changes_requested'?'Revise':'View decision'}</button></article>`).join('')}</div>`:prEmpty('No proposals to review','Create a proposal with a clear impact and scope before requesting a decision.')}</section></div>`;host.querySelectorAll('[data-proposal-review]').forEach(button=>button.onclick=()=>reviewProjectProposal(button.dataset.proposalReview));bindProjectActions()}
function renderProjectDiscussions(host,p){host.innerHTML=`<div class="project-page"><div class="project-section-head"><div><h2>Discussions</h2><p class="project-muted">Keep focused decisions and questions separate from project chat.</p></div>${prButton('＋ Start discussion','new-discussion','primary')}</div>${p.threads.length?`<div class="project-inline-list">${p.threads.map(thread=>`<article class="project-panel"><div class="project-discussion-row"><div><strong>${prEsc(thread.title)}</strong><small>${thread.replies.length} ${thread.replies.length===1?'reply':'replies'} · updated ${prEsc(prRelative(thread.updated_at))}</small><div class="project-thread-replies">${thread.replies.map(reply=>`<p><b>${prEsc(reply.author==='owner'?'You':reply.author)}:</b> ${prEsc(reply.content)}</p>`).join('')}</div></div><button type="button" class="project-btn quiet" data-project-reply="${prEsc(thread.id)}">Reply</button></div></article>`).join('')}</div>`:prEmpty('No discussions yet','Start a thread for a decision, question, or review topic.',prButton('Start a discussion','new-discussion','primary'))}</div>`;bindProjectActions()}
function renderProjectActivity(host,p){host.innerHTML=`<div class="project-page"><div class="project-section-head"><div><h2>Project activity</h2><p class="project-muted">A saved timeline of project changes and Vishnu requests.</p></div><span class="project-tag">${p.activity.length} events</span></div>${p.activity.length?`<div class="project-inline-list">${p.activity.map(item=>`<article class="project-activity-row"><span class="project-file-icon">${item.actor==='vishnu'?'✦':'•'}</span><div><strong>${prEsc(item.action)}</strong><small>${prEsc(item.detail||item.target_type)} · ${prEsc(prDate(item.created_at))}</small></div><span class="project-tag">${prEsc(item.actor)}</span></article>`).join('')}</div>`:prEmpty('No activity yet','Project edits, tasks, discussions and requests to Vishnu appear here.')}</div>`}
function renderProjectLive(host,p){const running=p.tasks.filter(task=>task.status==='in_progress'),paused=p.tasks.filter(task=>task.status==='paused'),blocked=p.tasks.filter(task=>task.status==='blocked');host.innerHTML=`<div class="project-page"><section class="project-panel"><div class="project-section-head"><div><h2>Live work</h2><p class="project-muted">Task state in this project. Starting a governed operation remains under Workflows and its approval controls.</p></div><span class="project-tag active">${running.length} active tasks</span></div>${running.length?`<div class="project-inline-list">${running.map(task=>`<article class="project-item-row"><i class="project-dot"></i><div><strong>${prEsc(task.title)}</strong><small>${prEsc(task.owner==='vishnu'?'Assigned to Vishnu':'Assigned to you')} · updated ${prEsc(prRelative(task.updated_at))}</small></div><button class="project-btn quiet" type="button" data-project-pause="${prEsc(task.id)}">Pause task</button></article>`).join('')}</div>`:prEmpty('No active project tasks','Move a task to In progress when work begins.')}</section>${paused.length?`<section class="project-panel"><h2>Paused</h2>${paused.map(task=>`<div class="project-item-row"><i class="project-dot paused"></i><div><strong>${prEsc(task.title)}</strong><small>Progress is saved in this project.</small></div><button class="project-btn quiet" type="button" data-project-resume="${prEsc(task.id)}">Resume</button></div>`).join('')}</section>`:''}${blocked.length?`<section class="project-panel"><h2>Needs your input</h2>${blocked.map(task=>`<div class="project-item-row"><i class="project-dot blocked"></i><div><strong>${prEsc(task.title)}</strong><small>Blocked · add a discussion or ask Vishnu to clarify what is needed.</small></div><button class="project-btn quiet" type="button" data-project-ask-task="${prEsc(task.id)}">Ask Vishnu</button></div>`).join('')}</section>`:''}<section class="project-panel"><h2>Approvals</h2><p class="project-muted">Review real pending Vishnu tool actions. Approving one runs only the action shown in its approval details.</p>${prButton('Review pending approvals','review-owner-approvals','quiet')}</section></div>`;bindProjectActions()}
function renderProjectStatus(host,p){const counts={planned:p.tasks.filter(t=>t.status==='planned').length,active:p.tasks.filter(t=>t.status==='in_progress').length,blocked:p.tasks.filter(t=>t.status==='blocked').length,done:p.tasks.filter(t=>t.status==='done').length};host.innerHTML=`<div class="project-page"><div class="project-section-head"><div><h2>Project status</h2><p class="project-muted">Live counts from saved project tasks; this map does not imply background agent activity.</p></div><span class="project-tag ${counts.blocked?'':'done'}">${counts.blocked?'Needs attention':'On track'}</span></div><section class="project-status-map" role="img" aria-label="Project status: ${counts.active} active, ${counts.planned} planned, ${counts.blocked} blocked, ${counts.done} completed tasks"><div class="project-status-orbit"></div><div class="project-status-core"><div><strong>${prEsc(p.name)}</strong><span>${prProgress(p)}% complete</span></div></div><div class="project-status-node n1">In progress<em>${counts.active}</em></div><div class="project-status-node n2">Planned<em>${counts.planned}</em></div><div class="project-status-node n3">Blocked<em>${counts.blocked}</em></div><div class="project-status-node n4">Completed<em>${counts.done}</em></div></section><div class="project-stat-grid"><div class="project-stat"><strong>${counts.active}</strong><span>In progress</span></div><div class="project-stat"><strong>${counts.blocked}</strong><span>Blocked</span></div><div class="project-stat"><strong>${counts.done}/${p.tasks.length}</strong><span>Completed</span></div></div></div>`}
function renderProjectStructure(host,p){const nodes=[{id:'goal',label:(p.goal||p.name).slice(0,40),sub:'Project goal',x:32,y:125,w:190,h:62,goal:true},...p.milestones.slice(0,4).map((m,i)=>({id:'m'+i,label:m.title.slice(0,26),sub:'Milestone · '+m.status,x:290,y:28+i*84,w:170,h:56})),...p.tasks.slice(0,6).map((t,i)=>({id:'t'+i,label:t.title.slice(0,27),sub:'Task · '+t.status,x:550,y:15+i*49,w:190,h:46}))];const edges=[...p.milestones.slice(0,4).map((_,i)=>['goal','m'+i]),...p.tasks.slice(0,6).map((_,i)=>[p.milestones.length?'m'+Math.min(i%Math.min(p.milestones.length,4),3):'goal','t'+i])];host.innerHTML=`<div class="project-page"><div class="project-section-head"><div><h2>Project structure</h2><p class="project-muted">A relationship map of this project’s goal, milestones and tasks. Scroll sideways on a phone.</p></div><span class="project-tag">${nodes.length} nodes</span></div><div class="project-structure" role="img" aria-label="Project relationship map"><svg viewBox="0 0 780 340" preserveAspectRatio="xMinYMin meet">${edges.map(([a,b])=>{const from=nodes.find(n=>n.id===a),to=nodes.find(n=>n.id===b);return from&&to?`<line x1="${from.x+from.w}" y1="${from.y+from.h/2}" x2="${to.x}" y2="${to.y+to.h/2}"/>`:''}).join('')}${nodes.map(node=>`<g><rect class="${node.goal?'goal':''}" x="${node.x}" y="${node.y}" width="${node.w}" height="${node.h}"/><text x="${node.x+12}" y="${node.y+23}">${prEsc(node.label)}</text><text class="sub" x="${node.x+12}" y="${node.y+42}">${prEsc(node.sub)}</text></g>`).join('')}${!p.tasks.length&&!p.milestones.length?'<text x="290" y="220" class="sub">Add milestones and tasks to map project structure.</text>':''}</svg></div></div>`}

async function refreshProject(){if(projectCurrent){const data=await api('/projects/'+encodeURIComponent(projectCurrent.id));projectCurrent=data.project;renderProjectDetail()}else await loadProjectList()}
async function updateProjectTask(taskId,fields){try{const data=await api(`/projects/${encodeURIComponent(projectCurrent.id)}/tasks/${encodeURIComponent(taskId)}`,{method:'PATCH',body:JSON.stringify(fields)});projectCurrent=data.project;renderProjectDetail()}catch(error){showToast(error.message)}}
let projectWizardState=null;
const projectDraftKey='vishnu-project-setup-draft-v1';
function readProjectDraft(){try{return JSON.parse(localStorage.getItem(projectDraftKey)||'null')}catch{return null}}
function persistProjectDraft(){if(!projectWizardState)return;try{const state={step:projectWizardState.step,fields:projectWizardState.fields,context_notes:projectWizardState.context_notes,links:projectWizardState.links,plan:projectWizardState.plan,fileNames:projectWizardState.files.map(file=>({name:file.name,size:file.size,type:file.type}))};localStorage.setItem(projectDraftKey,JSON.stringify(state))}catch{showToast('The browser could not save this draft. Keep this page open until you create the project.')}}
function createProject(){const saved=readProjectDraft();if(saved&&window.confirm('Resume your saved project draft? Choose Cancel to start a new draft.'))projectWizardState={...saved,files:[],needsFiles:Boolean(saved.fileNames?.length)};else projectWizardState={step:1,fields:{name:'',project_type:'software',goal:'',success_criteria:'',target_date:'',instructions:''},context_notes:'',links:[],files:[],plan:{milestones:[],tasks:[]},needsFiles:false};renderProjectWizard()}
function wizardStepMarkup(){return `<nav class="project-wizard-steps" aria-label="Project setup steps">${[['Details',1],['Context',2],['Review plan',3]].map(([label,step])=>`<button type="button" data-wizard-step="${step}" class="${projectWizardState.step===step?'current':projectWizardState.step>step?'complete':''}" aria-current="${projectWizardState.step===step?'step':'false'}"><i>${step}</i><span>${label}</span></button>`).join('')}</nav>`}
function renderProjectWizard(){
 const state=projectWizardState,host=document.getElementById('moduleBody');if(!state||!host)return;persistProjectDraft();const f=state.fields;
 const side=`<aside class="project-wizard-side"><section class="project-panel"><h2>What happens next?</h2><ol><li><b>Add files or connect project sources</b><span>Bring in relevant files, links, or other sources for context.</span></li><li><b>Review and edit a starter plan</b><span>Vishnu plan generation is not configured here; you control every plan item.</span></li><li><b>Work starts only after you approve the plan.</b><span>Creating the project saves planned tasks; it does not start execution.</span></li></ol><p class="project-privacy-note">🔒 Project files and memory stay scoped to this project.</p></section><section class="project-panel"><h2>Project workspace includes</h2><ul class="project-workspace-includes">${[['Overview','Goal and progress'],['Chat','Project-scoped conversation'],['Work plan','Tasks and milestones'],['Files & sources','Private project files'],['Discussions','Notes and decisions'],['Activity','Saved project changes'],['Live work','Current task states'],['3D views','Status and structure']].map(([a,b])=>`<li><b>${a}</b><span>${b}</span></li>`).join('')}</ul></section></aside>`;
 let main='';
 if(state.step===1)main=`<div class="project-wizard-form"><label>Project name <em>*</em><input name="name" maxlength="120" required placeholder="e.g. Personal AI mobile redesign" value="${prEsc(f.name)}"></label><label>Project type<select name="project_type"><option value="software" ${f.project_type==='software'?'selected':''}>Software & product</option><option value="business" ${f.project_type==='business'?'selected':''}>Business</option><option value="research" ${f.project_type==='research'?'selected':''}>Research</option><option value="writing" ${f.project_type==='writing'?'selected':''}>Writing</option><option value="personal" ${f.project_type==='personal'?'selected':''}>Personal</option></select><small>Choose the type that best fits your project.</small></label><label>Goal <em>*</em><textarea name="goal" maxlength="500" required rows="4" placeholder="Tell Vishnu what you want to accomplish…">${prEsc(f.goal)}</textarea><small class="project-char-count" data-count-for="goal">${f.goal.length}/500</small></label><label>Success criteria <span>(optional)</span><textarea name="success_criteria" maxlength="500" rows="3" placeholder="How will you know this project is successful?">${prEsc(f.success_criteria)}</textarea><small class="project-char-count" data-count-for="success_criteria">${f.success_criteria.length}/500</small></label><label>Target date <span>(optional)</span><input type="date" name="target_date" min="${new Date().toISOString().slice(0,10)}" value="${prEsc(f.target_date)}"></label><details class="project-instructions" ${f.instructions?'open':''}><summary>Instructions for Vishnu <span>(optional)</span></summary><label><span class="sr-only">Instructions for Vishnu</span><textarea name="instructions" maxlength="500" rows="3" placeholder="Rules, preferences, or constraints Vishnu should follow…">${prEsc(f.instructions)}</textarea><small class="project-char-count" data-count-for="instructions">${f.instructions.length}/500</small></label></details><div class="project-privacy-note">🔒 Project files and memory stay scoped to this project by default.</div></div>`;
 if(state.step===2)main=`<div class="project-wizard-form"><div class="project-step-intro"><h2>Add project context</h2><p>Choose files or links to include in this project. Nothing is uploaded until you create the project.</p></div><label class="project-upload-zone" id="wizardDropZone"><span aria-hidden="true">⇧</span><b>Drag and drop files here</b><span>PDF, DOCX, XLSX, CSV, TXT, MD, PNG, JPG or WebP · up to 12 MB each</span><button type="button" class="project-btn primary" data-wizard-upload>＋ Choose files</button><input id="wizardFileInput" type="file" hidden multiple accept=".pdf,.docx,.xlsx,.csv,.txt,.md,.png,.jpg,.jpeg,.webp"></label><section class="project-wizard-selection"><h3>Selected files (${state.files.length}${state.needsFiles?` · ${state.fileNames?.length||0} need reselecting`:''})</h3>${state.files.map((file,index)=>`<div class="project-source-pending"><span>▤</span><div><b>${prEsc(file.name)}</b><small>${(file.size/1024/1024).toFixed(2)} MB · Selected</small></div><button type="button" aria-label="Remove ${prEsc(file.name)}" data-remove-wizard-file="${index}">×</button></div>`).join('')||'<p class="project-muted">No files selected. You can continue without files.</p>'}${state.needsFiles?'<p class="project-inline-warning">File contents are not stored in the local draft. Re-select these files to include them.</p>':''}</section><form id="wizardLinkForm" class="project-link-form"><label>Link a source<input name="url" type="url" placeholder="https://…" required></label><label>Source name<input name="title" maxlength="180" placeholder="Research source" required></label><button class="project-btn quiet" type="submit">Add link</button></form><div class="project-wizard-selection"><h3>Project links (${state.links.length})</h3>${state.links.map((link,index)=>`<div class="project-source-pending"><span>↗</span><div><b>${prEsc(link.title)}</b><small>${prEsc(link.url)}</small></div><button type="button" aria-label="Remove ${prEsc(link.title)}" data-remove-wizard-link="${index}">×</button></div>`).join('')||'<p class="project-muted">No linked sources yet.</p>'}</div><label>Context notes <span>(optional)</span><textarea name="context_notes" rows="4" maxlength="4000" placeholder="What else should Vishnu know about this project?">${prEsc(state.context_notes)}</textarea></label><div class="project-privacy-note">🔒 Project files are private to this owner workspace. Source indexing varies by file type; only supported text files are included in project chat context.</div></div>`;
 if(state.step===3)main=`<div class="project-wizard-form"><div class="project-step-intro"><h2>Review your starter plan</h2><p>This is a manual proposal. Add the milestones and tasks you want to save. No work starts when you create the project.</p></div><div class="project-plan-builder"><div class="project-section-head"><div><h3>Milestones / phases</h3><p class="project-muted">Define outcomes and completion criteria.</p></div><button type="button" class="project-btn quiet" data-wizard-add-milestone>＋ Add phase</button></div>${state.plan.milestones.map((item,index)=>`<article class="project-plan-draft-row"><span class="project-plan-number">${index+1}</span><div><b>${prEsc(item.title)}</b><small>${prEsc(item.outcome)} · Due ${prEsc(prDate(item.target_date))}</small><small>Criteria: ${prEsc(item.completion_criteria)}</small></div><button type="button" aria-label="Remove ${prEsc(item.title)}" data-remove-wizard-milestone="${prEsc(item.client_id)}">×</button></article>`).join('')||'<p class="project-muted">No phases added. You can create the project without a plan.</p>'}<div class="project-section-head"><div><h3>Tasks</h3><p class="project-muted">Saved as Planned. Assigning a task to Vishnu does not start it.</p></div><button type="button" class="project-btn quiet" data-wizard-add-task>＋ Add task</button></div>${state.plan.tasks.map(item=>{const m=state.plan.milestones.find(value=>value.client_id===item.milestone_client_id);return `<article class="project-plan-draft-row"><span class="project-plan-number">☷</span><div><b>${prEsc(item.title)}</b><small>${prEsc(item.owner==='vishnu'?'Vishnu':'You')} · ${prEsc(item.priority)} priority${m?' · '+prEsc(m.title):''}</small>${item.description?`<small>${prEsc(item.description)}</small>`:''}</div><button type="button" aria-label="Remove ${prEsc(item.title)}" data-remove-wizard-task="${prEsc(item.client_id)}">×</button></article>`}).join('')||'<p class="project-muted">No tasks added yet.</p>'}</div><div class="project-privacy-note">Review the details above. Project creation stores your proposed plan; work only begins if you start a task later.</div></div>`;
 host.innerHTML=`<div class="project-page project-wizard-page"><div class="project-breadcrumb"><button type="button" data-wizard-cancel>‹ Projects</button><span>/</span><span>New project</span></div><header class="project-wizard-heading"><h1>Create a project</h1><p>Give Vishnu the context to help you plan and do the work.</p></header>${wizardStepMarkup()}<div class="project-wizard-layout"><section class="project-wizard-main" aria-live="polite">${main}</section>${side}</div><footer class="project-wizard-actions">${state.step===1?`<button type="button" class="project-btn quiet" data-wizard-save>▤ Save draft</button>`:state.step>1?`<button type="button" class="project-btn quiet" data-wizard-back>Back</button>`:''}<span class="project-wizard-action-spacer"></span><button type="button" class="project-btn quiet" data-wizard-cancel>Cancel</button>${state.step<3?`<button type="button" class="project-btn primary" data-wizard-next>${state.step===1?'Continue to context':'Review plan'} →</button>`:`<button type="button" class="project-btn primary" data-wizard-create>Create project</button>`}</footer></div>`;
 host.querySelectorAll('[data-wizard-step]').forEach(button=>button.onclick=()=>{const step=Number(button.dataset.wizardStep);if(step<=state.step&&step>=1){state.step=step;renderProjectWizard()}});
 host.querySelectorAll('input[name],textarea[name],select[name]').forEach(control=>control.addEventListener('input',()=>{if(control.name==='context_notes')state.context_notes=control.value;else state.fields[control.name]=control.value;const counter=host.querySelector(`[data-count-for="${control.name}"]`);if(counter)counter.textContent=`${control.value.length}/500`;persistProjectDraft()}));
 host.querySelector('[data-wizard-next]')?.addEventListener('click',()=>{if(state.step===1){const form=host.querySelector('.project-wizard-form');if(!form.querySelector('[name="name"]').reportValidity()||!form.querySelector('[name="goal"]').reportValidity())return;if(!state.fields.project_type){showToast('Choose a project type.');return}}state.step++;renderProjectWizard()});
 host.querySelector('[data-wizard-back]')?.addEventListener('click',()=>{state.step--;renderProjectWizard()});host.querySelector('[data-wizard-save]')?.addEventListener('click',()=>{persistProjectDraft();showToast('Project draft saved on this device.')});host.querySelectorAll('[data-wizard-cancel]').forEach(button=>button.onclick=cancelProjectWizard);
 host.querySelector('[data-wizard-upload]')?.addEventListener('click',()=>host.querySelector('#wizardFileInput').click());
 const input=host.querySelector('#wizardFileInput');input?.addEventListener('change',()=>{const allowed=new Set(['pdf','docx','xlsx','csv','txt','md','png','jpg','jpeg','webp']);for(const file of Array.from(input.files||[])){const ext=file.name.split('.').pop().toLowerCase();if(file.size>12*1024*1024){showToast(`${file.name} is larger than the 12 MB upload limit.`);continue}if(!allowed.has(ext)){showToast(`${file.name} is not a supported project file.`);continue}if(state.files.some(item=>item.name===file.name&&item.size===file.size)){showToast(`${file.name} is already selected.`);continue}state.files.push(file)}state.needsFiles=false;renderProjectWizard()});
 const drop=host.querySelector('#wizardDropZone');drop?.addEventListener('dragover',event=>{event.preventDefault();drop.classList.add('dragging')});drop?.addEventListener('dragleave',()=>drop.classList.remove('dragging'));drop?.addEventListener('drop',event=>{event.preventDefault();drop.classList.remove('dragging');const transfer=new DataTransfer();Array.from(event.dataTransfer.files).forEach(file=>transfer.items.add(file));input.files=transfer.files;input.dispatchEvent(new Event('change'))});
 host.querySelector('#wizardLinkForm')?.addEventListener('submit',event=>{event.preventDefault();const data=Object.fromEntries(new FormData(event.currentTarget));try{const url=new URL(data.url);if(!['https:','http:'].includes(url.protocol))throw new Error();state.links.push({title:data.title.trim(),url:url.href});renderProjectWizard()}catch{showToast('Enter a valid http or https link.')}});
 host.querySelectorAll('[data-remove-wizard-file]').forEach(button=>button.onclick=()=>{state.files.splice(Number(button.dataset.removeWizardFile),1);renderProjectWizard()});host.querySelectorAll('[data-remove-wizard-link]').forEach(button=>button.onclick=()=>{state.links.splice(Number(button.dataset.removeWizardLink),1);persistProjectDraft();renderProjectWizard()});
 host.querySelector('[data-wizard-add-milestone]')?.addEventListener('click',async()=>{const item=await projectDialog('Add plan phase',[{name:'title',label:'Milestone name',required:true,maxLength:180},{name:'outcome',label:'Outcome',type:'textarea',required:true,maxLength:2000},{name:'target_date',label:'Target date',type:'date',required:true},{name:'completion_criteria',label:'Completion criteria',type:'textarea',required:true,maxLength:2000}]);if(item){state.plan.milestones.push({...item,client_id:crypto.randomUUID()});persistProjectDraft();renderProjectWizard()}});
 host.querySelector('[data-wizard-add-task]')?.addEventListener('click',async()=>{const options=[['','No milestone'],...state.plan.milestones.map(item=>[item.client_id,item.title])];const item=await projectDialog('Add planned task',[{name:'title',label:'Task name',required:true,maxLength:180},{name:'description',label:'Description / context',type:'textarea',maxLength:4000},{name:'owner',label:'Owner',type:'select',value:'owner',options:[['owner','You'],['vishnu','Vishnu']]},{name:'priority',label:'Priority',type:'select',value:'medium',options:[['low','Low'],['medium','Medium'],['high','High']]},{name:'due_date',label:'Due date',type:'date'},{name:'milestone_client_id',label:'Linked milestone',type:'select',options}]);if(item){state.plan.tasks.push({...item,client_id:crypto.randomUUID()});persistProjectDraft();renderProjectWizard()}});
 host.querySelectorAll('[data-remove-wizard-milestone]').forEach(button=>button.onclick=()=>{const id=button.dataset.removeWizardMilestone;state.plan.milestones=state.plan.milestones.filter(item=>item.client_id!==id);state.plan.tasks.forEach(task=>{if(task.milestone_client_id===id)task.milestone_client_id=null});persistProjectDraft();renderProjectWizard()});host.querySelectorAll('[data-remove-wizard-task]').forEach(button=>button.onclick=()=>{state.plan.tasks=state.plan.tasks.filter(item=>item.client_id!==button.dataset.removeWizardTask);persistProjectDraft();renderProjectWizard()});
 host.querySelector('[data-wizard-create]')?.addEventListener('click',submitProjectWizard)
}
async function cancelProjectWizard(){if(projectWizardState&&(projectWizardState.fields.name||projectWizardState.fields.goal||projectWizardState.files.length||projectWizardState.plan.tasks.length||projectWizardState.plan.milestones.length)&&!await requestConfirmation('Discard this project setup? Saved draft details remain available on this device.'))return;projectWizardState=null;loadProjectList()}
async function submitProjectWizard(){
 const state=projectWizardState;if(!state)return;const button=document.querySelector('[data-wizard-create]');if(button){button.disabled=true;button.textContent='Creating project…'}
 try{const projectPayload={...state.fields,context_notes:state.context_notes,description:'',tasks:state.plan.tasks.map(({client_id,...task})=>({...task,milestone_client_id:task.milestone_client_id||null})),milestones:state.plan.milestones};const result=await api('/projects',{method:'POST',body:JSON.stringify(projectPayload)});let project=result.project,failures=[];
 for(const file of state.files){try{const content=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(new Error('Could not read '+file.name));reader.readAsDataURL(file)});const uploaded=await api(`/projects/${encodeURIComponent(project.id)}/files/upload`,{method:'POST',body:JSON.stringify({filename:file.name,media_type:file.type||'application/octet-stream',content_base64:content})});project=uploaded.project}catch(error){failures.push(`${file.name}: ${error.message}`)}}
 for(const link of state.links){try{const linked=await api(`/projects/${encodeURIComponent(project.id)}/files`,{method:'POST',body:JSON.stringify(link)});project=linked.project}catch(error){failures.push(`${link.title}: ${error.message}`)}}
 try{localStorage.removeItem(projectDraftKey)}catch{}projectWizardState=null;projectCurrent=project;projectTab='overview';renderProjectDetail();showToast(failures.length?`Project saved. Some sources were not added: ${failures.join('; ')}`:'Project created. Its plan is saved as planned work and has not started.')
 }catch(error){if(button){button.disabled=false;button.textContent='Create project'}showToast(error.message||'Project could not be created. Your draft is still saved.')}
}
async function editProject(){const p=projectCurrent;if(!p)return;const value=await projectDialog('Edit project',[{name:'name',label:'Project name',required:true,maxLength:120},{name:'project_type',label:'Project type',type:'select',options:[['software','Software & product'],['business','Business'],['research','Research'],['writing','Writing'],['personal','Personal']]},{name:'goal',label:'Goal',type:'textarea',maxLength:500},{name:'success_criteria',label:'Success criteria',type:'textarea',maxLength:500},{name:'instructions',label:'Instructions for Vishnu',type:'textarea',maxLength:500},{name:'context_notes',label:'Context notes',type:'textarea',maxLength:4000},{name:'target_date',label:'Target date',type:'date'},{name:'status',label:'Project status',type:'select',options:[['active','Active'],['paused','Paused'],['completed','Completed']]}],p);if(!value)return;try{const result=await api('/projects/'+encodeURIComponent(p.id),{method:'PATCH',body:JSON.stringify(value)});projectCurrent=result.project;renderProjectDetail();showToast('Project updated.')}catch(error){showToast(error.message)}}
async function editProjectFromList(project){const value=await projectDialog('Edit project',[{name:'name',label:'Project name',required:true,maxLength:120},{name:'goal',label:'Goal',type:'textarea',maxLength:500},{name:'target_date',label:'Target date',type:'date'}],project);if(!value)return;try{await api('/projects/'+encodeURIComponent(project.id),{method:'PATCH',body:JSON.stringify(value)});await loadProjectList();showToast('Project updated.')}catch(error){showToast(error.message)}}
async function archiveProject(projectId){const project=projectRows.find(item=>item.id===projectId);if(!project||!await requestConfirmation(`Archive “${project.name}”? It remains available under Archived and can be restored.`))return;try{await api('/projects/'+encodeURIComponent(projectId),{method:'DELETE'});await loadProjectList();showToast('Project archived.')}catch(error){showToast(error.message)}}
async function restoreProject(projectId){try{await api('/projects/'+encodeURIComponent(projectId)+'/restore',{method:'POST',body:'{}'});projectListFilter='all';await loadProjectList();showToast('Project restored.')}catch(error){showToast(error.message)}}
async function setProjectStatus(status){if(!projectCurrent)return;try{const result=await api('/projects/'+encodeURIComponent(projectCurrent.id),{method:'PATCH',body:JSON.stringify({status})});projectCurrent=result.project;renderProjectDetail();showToast(status==='paused'?'Project paused.':'Project resumed.')}catch(error){showToast(error.message)}}
async function createProjectTask(){const p=projectCurrent;if(!p)return;const options=[['','No milestone'],...p.milestones.map(m=>[m.id,m.title])],fileOptions=(p.files||[]).map(file=>[file.id,file.title]);const value=await projectDialog('Create task',[{name:'title',label:'Task name',required:true,maxLength:180,placeholder:'Describe one concrete next step'},{name:'description',label:'Description',type:'textarea',maxLength:4000},{name:'context_notes',label:'Attached context notes / source links (optional)',type:'textarea',maxLength:2000},{name:'file_ids',label:'Attach project files',type:'checklist',options:fileOptions},{name:'owner',label:'Assign to',type:'select',value:'vishnu',required:true,options:[['vishnu','Vishnu'],['owner','You']]},{name:'status',label:'Status',type:'select',value:'planned',required:true,options:[['planned','Planned'],['in_progress','In progress'],['blocked','Blocked'],['needs_review','Needs review'],['paused','Paused'],['done','Complete'],['failed','Failed']]},{name:'priority',label:'Priority',type:'select',value:'medium',required:true,options:[['low','Low'],['medium','Medium'],['high','High']]},{name:'due_date',label:'Due date',type:'date'},{name:'milestone_id',label:'Milestone',type:'select',options}]);if(!value)return;try{const result=await api(`/projects/${encodeURIComponent(p.id)}/tasks`,{method:'POST',body:JSON.stringify({...value,file_ids:value.file_ids||[]})});projectCurrent=result.project;renderProjectDetail();showToast('Task saved to the work plan. No work was started.')}catch(error){showToast(error.message)}}
async function editProjectTask(taskId){const task=projectCurrent?.tasks.find(item=>item.id===taskId);if(!task)return;const fileOptions=(projectCurrent.files||[]).map(file=>[file.id,file.title]);const value=await projectDialog('Edit task',[{name:'title',label:'Task name',required:true,maxLength:180},{name:'description',label:'Description',type:'textarea',maxLength:4000},{name:'context_notes',label:'Attached context notes / source links (optional)',type:'textarea',maxLength:2000},{name:'file_ids',label:'Attach project files',type:'checklist',options:fileOptions},{name:'owner',label:'Assign to',type:'select',required:true,options:[['vishnu','Vishnu'],['owner','You']]},{name:'status',label:'Status',type:'select',required:true,options:[['planned','Planned'],['in_progress','In progress'],['blocked','Blocked'],['needs_review','Needs review'],['paused','Paused'],['done','Complete'],['failed','Failed']]},{name:'priority',label:'Priority',type:'select',required:true,options:[['low','Low'],['medium','Medium'],['high','High']]},{name:'due_date',label:'Due date',type:'date'}],task);if(!value)return;try{const result=await api(`/projects/${encodeURIComponent(projectCurrent.id)}/tasks/${encodeURIComponent(taskId)}`,{method:'PATCH',body:JSON.stringify({...value,file_ids:value.file_ids||[]})});projectCurrent=result.project;renderProjectDetail();showToast('Task updated.')}catch(error){showToast(error.message)}}
async function createProjectProposal(){const p=projectCurrent;if(!p)return;const value=await projectDialog('New approval proposal',[{name:'title',label:'Proposal title',required:true,maxLength:180},{name:'summary',label:'Proposal summary',type:'textarea',required:true,maxLength:4000},{name:'impact_summary',label:'Impact summary',type:'textarea',required:true,maxLength:2000},{name:'scope_summary',label:'Scope summary',type:'textarea',required:true,maxLength:2000},{name:'task_ids',label:'Linked tasks',type:'checklist',options:p.tasks.map(item=>[item.id,item.title])},{name:'file_ids',label:'Related project files',type:'checklist',options:p.files.map(item=>[item.id,item.title])}]);if(!value)return;try{const result=await api(`/projects/${encodeURIComponent(p.id)}/approvals`,{method:'POST',body:JSON.stringify({...value,task_ids:value.task_ids||[],file_ids:value.file_ids||[]})});projectCurrent=result.project;renderProjectDetail();showToast('Proposal submitted for review.')}catch(error){showToast(error.message)}}
async function reviseProjectProposal(id){const p=projectCurrent,item=p?.approvals?.find(row=>row.id===id);if(!item)return;const value=await projectDialog('Revise proposal',[{name:'title',label:'Proposal title',required:true,maxLength:180},{name:'summary',label:'Proposal summary',type:'textarea',required:true,maxLength:4000},{name:'impact_summary',label:'Impact summary',type:'textarea',required:true,maxLength:2000},{name:'scope_summary',label:'Scope summary',type:'textarea',required:true,maxLength:2000},{name:'task_ids',label:'Linked tasks',type:'checklist',options:p.tasks.map(row=>[row.id,row.title])},{name:'file_ids',label:'Related project files',type:'checklist',options:p.files.map(row=>[row.id,row.title])}],item);if(!value)return;try{const result=await api(`/projects/${encodeURIComponent(p.id)}/approvals/${encodeURIComponent(id)}/resubmit`,{method:'POST',body:JSON.stringify({...value,task_ids:value.task_ids||[],file_ids:value.file_ids||[]})});projectCurrent=result.project;renderProjectDetail();showToast('Revised proposal resubmitted.')}catch(error){showToast(error.message)}}
async function reviewProjectProposal(id){const p=projectCurrent,item=p?.approvals?.find(row=>row.id===id);if(!item)return;if(item.status==='changes_requested')return reviseProjectProposal(id);const dialog=document.createElement('dialog');dialog.className='project-dialog project-approval-dialog';dialog.setAttribute('aria-labelledby','projectProposalReviewTitle');const tasks=new Map(p.tasks.map(row=>[row.id,row.title])),files=new Map(p.files.map(row=>[row.id,row.title]));const history=(item.history||[]).map(row=>`<p class="project-muted">${prEsc(row.decision.replaceAll('_',' '))} · ${prEsc(prDate(row.created_at))}${row.comments?' — '+prEsc(row.comments):''}</p>`).join('');dialog.innerHTML=`<form class="project-approval-view"><header class="project-dialog-head"><div><h2 id="projectProposalReviewTitle">Review proposal</h2><p>Project proposal · ${prEsc(item.status.replaceAll('_',' '))}</p></div><button class="project-dialog-close" type="button" aria-label="Close review">×</button></header><div class="project-dialog-fields"><div class="project-approval-banner"><b>${prEsc(item.status==='pending'?'Pending your review':item.status.replaceAll('_',' '))}</b><span>Decisions apply only to this proposal and do not start project work.</span></div><section class="project-approval-summary"><h3>${prEsc(item.title)}</h3><p>${prEsc(item.summary)}</p></section><div class="project-approval-facts"><div><b>Impact</b><span>${prEsc(item.impact_summary||'No impact summary provided')}</span></div><div><b>Scope</b><span>${prEsc(item.scope_summary||'No scope summary provided')}</span></div><div><b>Linked tasks</b><span>${(item.task_ids||[]).map(id=>tasks.get(id)).filter(Boolean).map(prEsc).join(', ')||'None'}</span></div><div><b>Related files</b><span>${(item.file_ids||[]).map(id=>files.get(id)).filter(Boolean).map(prEsc).join(', ')||'None'}</span></div></div>${item.reviewer_comments?`<section class="project-approval-summary"><b>Reviewer comments</b><p>${prEsc(item.reviewer_comments)}</p></section>`:''}${history?`<section class="project-approval-summary"><b>Decision history</b>${history}</section>`:''}${item.status==='pending'?'<label>Reviewer comments (required to request changes)<textarea name="comments" maxlength="4000" rows="3"></textarea></label>':''}<p class="project-source-status" role="status" aria-live="polite"></p></div><footer class="project-dialog-actions"><button type="button" class="project-btn quiet" data-proposal-close>Close</button>${item.status==='pending'?'<button type="button" class="project-btn quiet" data-proposal-changes>Request changes</button><button type="button" class="project-btn primary" data-proposal-approve>Approve &amp; continue</button>':''}</footer></form>`;document.body.append(dialog);const close=()=>dialog.close();dialog.querySelector('.project-dialog-close').onclick=close;dialog.querySelector('[data-proposal-close]')?.addEventListener('click',close);dialog.addEventListener('close',()=>dialog.remove());dialog.addEventListener('cancel',event=>{event.preventDefault();close()});const decide=async decision=>{const comments=dialog.querySelector('[name=comments]')?.value||'';if(decision==='changes_requested'&&!comments.trim()){dialog.querySelector('[name=comments]').focus();return}const buttons=dialog.querySelectorAll('button');buttons.forEach(button=>button.disabled=true);dialog.querySelector('[role=status]').textContent='Saving decision…';try{const result=await api(`/projects/${encodeURIComponent(p.id)}/approvals/${encodeURIComponent(id)}/decision`,{method:'POST',body:JSON.stringify({decision,comments})});projectCurrent=result.project;dialog.querySelector('[role=status]').textContent=decision==='approved'?'Approved. No work was started.':'Changes requested. Comments were saved.';renderProjectDetail();showToast(decision==='approved'?'Proposal approved. No work was started.':'Changes requested and saved.');close()}catch(error){dialog.querySelector('[role=status]').textContent=error.message;buttons.forEach(button=>button.disabled=false)}};dialog.querySelector('[data-proposal-changes]')?.addEventListener('click',()=>decide('changes_requested'));dialog.querySelector('[data-proposal-approve]')?.addEventListener('click',()=>decide('approved'));dialog.showModal()}

async function createProjectMilestone(){const p=projectCurrent;if(!p)return;const value=await projectDialog('Create milestone',[{name:'title',label:'Milestone name',required:true,maxLength:180},{name:'outcome',label:'Outcome / description',type:'textarea',required:true,maxLength:2000},{name:'target_date',label:'Target date',type:'date',required:true},{name:'task_ids',label:'Linked tasks',type:'checklist',options:p.tasks.map(task=>[task.id,task.title])},{name:'completion_criteria',label:'Completion criteria',type:'textarea',required:true,maxLength:2000}]);if(!value)return;try{const result=await api(`/projects/${encodeURIComponent(projectCurrent.id)}/milestones`,{method:'POST',body:JSON.stringify({...value,task_ids:value.task_ids||[]})});projectCurrent=result.project;renderProjectDetail();showToast('Milestone and task links saved.')}catch(error){showToast(error.message)}}
async function editProjectMilestone(id){const item=projectCurrent.milestones.find(value=>value.id===id);if(!item)return;const value=await projectDialog('Edit milestone',[{name:'title',label:'Milestone name',required:true,maxLength:180},{name:'outcome',label:'Outcome / description',type:'textarea',required:true,maxLength:2000},{name:'status',label:'Status',type:'select',options:[['planned','Planned'],['in_progress','In progress'],['blocked','Blocked'],['done','Complete']]},{name:'target_date',label:'Target date',type:'date',required:true},{name:'task_ids',label:'Linked tasks',type:'checklist',options:projectCurrent.tasks.map(task=>[task.id,task.title])},{name:'completion_criteria',label:'Completion criteria',type:'textarea',required:true,maxLength:2000}],{...item,task_ids:(item.task_ids||[])});if(!value)return;try{const result=await api(`/projects/${encodeURIComponent(projectCurrent.id)}/milestones/${encodeURIComponent(id)}`,{method:'PATCH',body:JSON.stringify({...value,task_ids:value.task_ids||[]})});projectCurrent=result.project;renderProjectDetail();showToast('Milestone updated.')}catch(error){showToast(error.message)}}
async function addProjectLink(){const value=await projectDialog('Add project source',[{name:'title',label:'Source name',required:true,maxLength:180,placeholder:'Research source'},{name:'url',label:'Web address',type:'url',required:true,maxLength:2000,placeholder:'https://…'}]);if(!value)return;try{const result=await api(`/projects/${encodeURIComponent(projectCurrent.id)}/files`,{method:'POST',body:JSON.stringify(value)});projectCurrent=result.project;renderProjectDetail();showToast('Source linked to this project.')}catch(error){showToast(error.message)}}
async function addProjectFiles(){
 const p=projectCurrent;if(!p)return;const dialog=document.createElement('dialog');dialog.className='project-dialog project-files-dialog';dialog.setAttribute('aria-labelledby','projectFilesTitle');dialog.innerHTML=`<form method="dialog" class="project-dialog-form"><header class="project-dialog-head"><div><h2 id="projectFilesTitle">Add files &amp; sources</h2><p>Upload files or add a trusted web source to this project.</p></div><button class="project-dialog-close" type="button" aria-label="Close dialog">×</button></header><div class="project-dialog-fields"><label class="project-upload-zone" data-drop-zone><span aria-hidden="true">⇧</span><b>Drag and drop files here</b><span>PDF, DOCX, XLSX, CSV, TXT, MD, PNG, JPG or WebP · 12 MB maximum per file</span><button type="button" class="project-btn primary" data-choose-files>＋ Upload files</button><input type="file" hidden multiple accept=".pdf,.docx,.xlsx,.csv,.txt,.md,.png,.jpg,.jpeg,.webp"></label><p class="project-source-status" role="status">Files stay staged until you select Add to project.</p><div class="project-staged-files" data-staged-files></div><section class="project-add-link"><h3>Connect a web source</h3><label>Source name<input name="source_title" maxlength="180" placeholder="Project brief"></label><label>URL<input name="source_url" type="url" placeholder="https://…"></label><small>External service connections are not configured in this installation.</small></section><div class="project-privacy-note">🔒 Project files are private and available only to this authorized owner workspace. Supported text files are included in project chat context; other formats are stored for download.</div></div><footer class="project-dialog-actions"><button type="button" class="project-btn quiet" data-files-cancel>Cancel</button><button type="submit" class="project-btn primary" data-files-submit>Add to project</button></footer></form>`;
 document.body.append(dialog);let staged=[];const uploadedFiles=new Set();const fileKey=file=>`${file.name}:${file.size}:${file.lastModified}`;const form=dialog.querySelector('form'),input=form.querySelector('input[type=file]'),close=()=>{if(dialog.open)dialog.close();dialog.remove()};dialog.querySelector('.project-dialog-close').onclick=dialog.querySelector('[data-files-cancel]').onclick=close;dialog.addEventListener('cancel',event=>{event.preventDefault();close()});const render=()=>{form.querySelector('[data-staged-files]').innerHTML=staged.map((file,index)=>`<div class="project-source-pending"><span>▤</span><div><b>${prEsc(file.name)}</b><small>${prEsc(file.type||file.name.split('.').pop().toUpperCase())} · ${(file.size/1024/1024).toFixed(2)} MB · ${uploadedFiles.has(fileKey(file))?'Added to project':'Ready to upload'}</small></div><button type="button" aria-label="Remove ${prEsc(file.name)}" data-remove-staged="${index}" ${uploadedFiles.has(fileKey(file))?'disabled title="Already saved to project"':''}>×</button></div>`).join('')||'<p class="project-muted">No files selected.</p>';form.querySelectorAll('[data-remove-staged]').forEach(button=>button.onclick=()=>{staged.splice(Number(button.dataset.removeStaged),1);render()})};const addFiles=files=>{for(const file of files){const ext=file.name.split('.').pop().toLowerCase();if(!['pdf','docx','xlsx','csv','txt','md','png','jpg','jpeg','webp'].includes(ext)){showToast(`${file.name} is not supported.`);continue}if(file.size>12*1024*1024){showToast(`${file.name} exceeds the 12 MB limit.`);continue}if(staged.some(item=>item.name===file.name&&item.size===file.size)||p.files.some(item=>item.title===file.name)){showToast(`${file.name} is already added or selected.`);continue}staged.push(file)}render()};dialog.querySelector('[data-choose-files]').onclick=()=>input.click();input.onchange=()=>addFiles(Array.from(input.files||[]));const zone=dialog.querySelector('[data-drop-zone]');zone.ondragover=event=>{event.preventDefault();zone.classList.add('dragging')};zone.ondragleave=()=>zone.classList.remove('dragging');zone.ondrop=event=>{event.preventDefault();zone.classList.remove('dragging');addFiles(Array.from(event.dataTransfer.files||[]))};form.onsubmit=async event=>{event.preventDefault();const submit=form.querySelector('[data-files-submit]'),title=form.elements.source_title.value.trim(),url=form.elements.source_url.value.trim();if(!staged.length&&!url){showToast('Choose a file or enter a source URL.');return}if(Boolean(title)!==Boolean(url)){showToast('Provide both a source name and its URL.');return}if(url){try{const parsed=new URL(url);if(!['https:','http:'].includes(parsed.protocol))throw new Error()}catch{showToast('Enter a valid http or https URL.');return}}submit.disabled=true;submit.textContent='Adding…';form.querySelector('.project-source-status').textContent='Uploading selected files and saving sources…';try{for(const file of staged){if(uploadedFiles.has(fileKey(file)))continue;const content=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(new Error(`${file.name} could not be read.`));reader.readAsDataURL(file)});const result=await api(`/projects/${encodeURIComponent(p.id)}/files/upload`,{method:'POST',body:JSON.stringify({filename:file.name,media_type:file.type||'application/octet-stream',content_base64:content})});projectCurrent=result.project;uploadedFiles.add(fileKey(file));form.querySelector('.project-source-status').textContent=`Uploaded ${file.name}. Continuing with remaining sources…`;render()}if(url){const result=await api(`/projects/${encodeURIComponent(p.id)}/files`,{method:'POST',body:JSON.stringify({title,url,kind:'link'})});projectCurrent=result.project}close();projectTab='files';renderProjectDetail();showToast('The selected files and sources were saved to this project.')}catch(error){submit.disabled=false;submit.textContent='Retry remaining';form.querySelector('.project-source-status').textContent=error.message+' Already completed uploads remain saved. Retry only the remaining items.';render();showToast(error.message)}};render();dialog.showModal();
}

async function openProjectApprovalReview(){
 let approvals=[];try{const response=await api('/approvals-center');approvals=Array.isArray(response.approvals)?response.approvals:[]}catch(error){showToast(error.message||'Could not load the approval queue.');return}
 const dialog=document.createElement('dialog');dialog.className='project-dialog project-approval-dialog';dialog.setAttribute('aria-labelledby','projectApprovalTitle');document.body.append(dialog);
 const close=()=>{if(dialog.open)dialog.close();dialog.remove()};
 const renderList=()=>{dialog.innerHTML=`<section class="project-approval-view"><header class="project-dialog-head"><div><h2 id="projectApprovalTitle">Review approvals</h2><p>Real pending system actions that require your decision.</p></div><button class="project-dialog-close" type="button" aria-label="Close approvals">×</button></header><div class="project-dialog-fields">${approvals.length?approvals.map(item=>`<article class="project-approval-row"><div><strong>${prEsc(item.tool_id||'Vishnu action')}</strong><small>${prEsc(item.destination||'No destination provided')} · ${prEsc(item.data_classification||'internal')} data</small><small>Expires ${prEsc(new Date(Number(item.expires_at)*1000).toLocaleString())}</small></div><button type="button" class="project-btn quiet" data-approval-open="${prEsc(item.approval_id)}">Review</button></article>`).join(''):`<div class="project-empty"><h2>No pending approvals</h2><p>There are no governed tool actions waiting for your review.</p></div>`}</div><footer class="project-dialog-actions"><button type="button" class="project-btn quiet" data-approval-close>Close</button></footer></section>`;dialog.querySelector('.project-dialog-close').onclick=dialog.querySelector('[data-approval-close]').onclick=close;dialog.querySelectorAll('[data-approval-open]').forEach(button=>button.onclick=()=>showApprovalDetail(button.dataset.approvalOpen))};
 const showApprovalDetail=async id=>{let item;try{item=await api('/approvals-center/'+encodeURIComponent(id))}catch(error){showToast(error.message||'This approval is no longer available.');return}if(item.status!=='pending'){showToast('This approval is no longer pending.');approvals=approvals.filter(row=>row.approval_id!==id);renderList();return}dialog.innerHTML=`<form class="project-approval-view" method="dialog"><header class="project-dialog-head"><div><h2 id="projectApprovalTitle">Review approval</h2><p>Inspect the exact governed action before deciding.</p></div><button class="project-dialog-close" type="button" aria-label="Close approval">×</button></header><div class="project-dialog-fields"><div class="project-approval-banner"><b>Pending system action</b><span>Approval executes only this action.</span></div><section class="project-approval-summary"><h3>${prEsc(item.tool_id||'Vishnu action')}</h3><p>${prEsc(item.destination||'No destination was provided by the action.')}</p></section><div class="project-approval-facts"><div><b>Scope</b><span>${prEsc(item.tool_id||'Action')} · ${prEsc(item.destination||'Destination not provided')}</span></div><div><b>Data classification</b><span>${prEsc(item.data_classification||'internal')}</span></div><div><b>Expires</b><span>${prEsc(new Date(Number(item.expires_at)*1000).toLocaleString())}</span></div><div><b>Project records</b><span>This system approval is not linked to a project proposal, task, or project file.</span></div></div><p class="project-dialog-note">This installation records approve or reject decisions for governed actions. Reviewer comments and “request changes” are not supported by the current approval service.</p><p class="project-source-status" role="status" aria-live="polite"></p></div><footer class="project-dialog-actions"><button type="button" class="project-btn quiet" data-approval-back>Back</button><button type="button" class="project-btn quiet" data-approval-reject>Reject action</button><button type="button" class="project-btn primary" data-approval-approve>Approve &amp; run action</button></footer></form>`;
 dialog.querySelector('.project-dialog-close').onclick=close;dialog.querySelector('[data-approval-back]').onclick=renderList;
 const decide=async decision=>{const controls=dialog.querySelectorAll('button');controls.forEach(button=>button.disabled=true);const status=dialog.querySelector('[role=status]');status.textContent=decision==='approve'?'Running the approved action…':'Saving rejection…';try{const result=await api(`/approval/${encodeURIComponent(id)}/${decision}`,{method:'POST',body:'{}'});status.textContent=decision==='approve'?`Approved. ${result.reply||'The action completed.'}`:'Action rejected.';approvals=approvals.filter(row=>row.approval_id!==id);showToast(status.textContent);setTimeout(()=>{if(dialog.isConnected)renderList()},900)}catch(error){status.textContent=error.message||'The decision could not be saved. The action was not approved.';controls.forEach(button=>button.disabled=false)}};
 dialog.querySelector('[data-approval-reject]').onclick=()=>decide('reject');dialog.querySelector('[data-approval-approve]').onclick=()=>decide('approve')};
 renderList();dialog.addEventListener('cancel',event=>{event.preventDefault();close()});dialog.addEventListener('click',event=>{if(event.target===dialog)close()});dialog.showModal();
}

async function startProjectDiscussion(){const value=await projectDialog('Start discussion',[{name:'title',label:'Topic',required:true,maxLength:180},{name:'content',label:'Message',type:'textarea',required:true,maxLength:4000}]);if(!value)return;try{const result=await api(`/projects/${encodeURIComponent(projectCurrent.id)}/discussions`,{method:'POST',body:JSON.stringify(value)});projectCurrent=result.project;renderProjectDetail();showToast('Discussion started.')}catch(error){showToast(error.message)}}
async function replyProjectDiscussion(threadId){const thread=projectCurrent.threads.find(item=>item.id===threadId),value=await projectDialog('Reply to discussion',[{name:'content',label:thread?.title||'Your reply',type:'textarea',required:true,maxLength:4000}]);if(!value)return;try{const result=await api(`/projects/${encodeURIComponent(projectCurrent.id)}/discussions/${encodeURIComponent(threadId)}/replies`,{method:'POST',body:JSON.stringify(value)});projectCurrent=result.project;renderProjectDetail()}catch(error){showToast(error.message)}}
async function askVishnuAboutTask(taskId){const task=projectCurrent?.tasks.find(item=>item.id===taskId);if(!task)return;try{const result=await api(`/projects/${encodeURIComponent(projectCurrent.id)}/tasks/${encodeURIComponent(taskId)}`,{method:'PATCH',body:JSON.stringify({owner:'vishnu'})});projectCurrent=result.project;projectTab='chat';renderProjectDetail();await new Promise(resolve=>setTimeout(resolve,50));const input=document.querySelector('#projectChatForm textarea');if(input){input.value=`Please help me work on this project task: ${task.title}${task.description?'. '+task.description:''}. First explain a safe plan and what information or approvals you need.`;input.focus()}}catch(error){showToast(error.message)}}
function bindProjectActions(){document.querySelectorAll('[data-project-action]').forEach(button=>{if(button.dataset.bound)return;button.dataset.bound='1';button.onclick=async()=>{const action=button.dataset.projectAction;if(action==='new-project')return createProject();if(action==='back'){projectCurrent=null;return loadProjectList()}if(action==='edit-project')return editProject();if(action==='new-task')return createProjectTask();if(action==='new-proposal')return createProjectProposal();if(action==='new-milestone')return createProjectMilestone();if(action==='new-file-link')return addProjectLink();if(action==='add-files')return addProjectFiles();if(action==='pause-project')return setProjectStatus('paused');if(action==='resume-project')return setProjectStatus('active');if(action==='review-owner-approvals')return openProjectApprovalReview();if(action==='new-discussion')return startProjectDiscussion();if(action==='go-chat'){projectTab='chat';return renderProjectDetail()}if(action==='reload')return projectCurrent?openProject(projectCurrent.id):loadProjectList();if(action==='project-chat-retry')return renderProjectTab();if(action==='open-workflows')return openModule('workflows')}});document.querySelectorAll('[data-project-task-edit]').forEach(button=>button.onclick=()=>editProjectTask(button.dataset.projectTaskEdit));document.querySelectorAll('[data-project-milestone-edit]').forEach(button=>button.onclick=()=>editProjectMilestone(button.dataset.projectMilestoneEdit));document.querySelectorAll('[data-project-ask-task]').forEach(button=>button.onclick=()=>askVishnuAboutTask(button.dataset.projectAskTask));document.querySelectorAll('[data-project-reply]').forEach(button=>button.onclick=()=>replyProjectDiscussion(button.dataset.projectReply));document.querySelectorAll('[data-project-pause]').forEach(button=>button.onclick=()=>updateProjectTask(button.dataset.projectPause,{status:'paused'}));document.querySelectorAll('[data-project-resume]').forEach(button=>button.onclick=()=>updateProjectTask(button.dataset.projectResume,{status:'in_progress'}))}

modules.projects=['Projects','Project workspaces with dedicated plans, sources, decisions and Vishnu conversations.',()=>`${projectRows.length} projects`];
const projectsOriginalOpenModule=openModule;
openModule=async function(name){if(name!=='projects')return projectsOriginalOpenModule(name);await projectsOriginalOpenModule('projects');document.body.classList.add('focused-module');await loadProjectList()};
